<script setup>
import { onUnmounted, ref, watch } from 'vue';
const props=defineProps({api:Function,tenant:Object,user:Object,canManage:Boolean,page:String});
const error=ref(''),notice=ref(''),busy=ref(false),team=ref(null),profile=ref({}),name=ref(props.user.name);
const email=ref(''),role=ref('viewer'),password=ref(''),removeTarget=ref(null);
let epoch=0;
async function load(){const token=++epoch;error.value='';try{const result=await props.api(`tenants/${props.tenant.id}/team`);if(token===epoch)team.value=result;}catch(e){if(token===epoch)error.value=e.message;}}
watch(()=>[props.tenant.id,props.page],()=>{profile.value={name:props.tenant.name,contact_name:props.tenant.contact_name,phone:props.tenant.phone,tax_code:props.tenant.tax_code,address:props.tenant.address};password.value='';notice.value='';removeTarget.value=null;load();},{immediate:true});
async function post(path,body){busy.value=true;error.value='';notice.value='';try{await props.api(path,{method:'POST',body:JSON.stringify(body)});notice.value='Đã lưu thay đổi.';await load();}catch(e){error.value=e.message;}finally{password.value='';busy.value=false;}}
async function remove(){busy.value=true;error.value='';try{await props.api(`tenants/${props.tenant.id}/members/${removeTarget.value.id}`,{method:'DELETE',body:JSON.stringify({current_password:password.value})});removeTarget.value=null;notice.value='Đã thu hồi quyền công ty của thành viên.';await load();}catch(e){error.value=e.message;}finally{password.value='';busy.value=false;}}
onUnmounted(()=>epoch++);
</script>
<template>
    <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success-notice" role="status">{{notice}}</p>
    <template v-if="page==='company'"><section class="panel"><h2>Hồ sơ doanh nghiệp</h2><form class="commerce-form" @submit.prevent="post(`tenants/${tenant.id}/profile`,profile)"><div class="form-columns"><label>Tên công ty<input v-model="profile.name" :disabled="!canManage" required maxlength="150"></label><label>Người liên hệ<input v-model="profile.contact_name" :disabled="!canManage" maxlength="120"></label><label>Số điện thoại<input v-model="profile.phone" :disabled="!canManage" maxlength="40"></label><label>Mã số thuế<input v-model="profile.tax_code" :disabled="!canManage" maxlength="40"></label></div><label>Địa chỉ<input v-model="profile.address" :disabled="!canManage" maxlength="500"></label><button v-if="canManage" class="primary" :disabled="busy">Lưu hồ sơ công ty</button></form></section><section class="panel"><h2>Tài khoản cá nhân</h2><p class="muted">{{user.email}} · Email đăng nhập không đổi từ chức năng này.</p><form class="commerce-form" @submit.prevent="post('profile',{name})"><label>Họ tên<input v-model="name" required maxlength="100"></label><button class="primary" :disabled="busy">Lưu tên hiển thị</button></form></section></template>
    <template v-if="page==='team'"><section v-if="team" class="panel"><h2>Thành viên công ty</h2><p class="muted">Quyền của công ty không phải quyền admin nền tảng TN20.</p><div class="table-scroll"><table><thead><tr><th>Họ tên</th><th>Email</th><th>Vai trò</th><th></th></tr></thead><tbody><tr v-for="member in team.members" :key="member.id"><td>{{member.name}}</td><td>{{member.email}}</td><td>{{({owner:'Chủ công ty',admin:'Quản trị công ty',operator:'Vận hành',viewer:'Chỉ xem'})[member.pivot.role]}}</td><td><button v-if="team.can_manage && member.pivot.role!=='owner'" class="secondary" @click="removeTarget=member;password=''">Thu hồi quyền</button></td></tr></tbody></table></div></section><section v-if="team?.can_manage" class="panel"><h2>Thêm thành viên / đổi vai trò</h2><p class="muted">Thành viên cần có tài khoản đã đăng ký. Chỉ chủ công ty được cấp quyền; tài khoản được thêm sẽ xem dữ liệu công ty theo vai trò đã chọn.</p><form class="commerce-form" @submit.prevent="post(`tenants/${tenant.id}/members`,{email,role,current_password:password})"><label>Email tài khoản<input v-model="email" type="email" required autocomplete="off"></label><label>Vai trò trong công ty<select v-model="role"><option value="viewer">Chỉ xem</option><option value="operator">Vận hành (quyền đọc trong bản hiện tại)</option><option value="admin">Quản trị công ty, gồm thông tin mua bán</option></select></label><label>Mật khẩu hiện tại của bạn<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy">Xác nhận cấp quyền công ty</button></form></section><section v-if="removeTarget" class="panel"><h2>Thu hồi quyền {{removeTarget.email}}</h2><p class="notice">Thành viên sẽ mất quyền truy cập công ty này. Tài khoản cá nhân và các công ty khác vẫn tồn tại.</p><form class="commerce-form" @submit.prevent="remove"><label>Mật khẩu hiện tại của bạn<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy">Xác nhận thu hồi</button><button class="text-button" type="button" @click="removeTarget=null">Hủy</button></form></section></template>
</template>
